1	//! Tests for proper spell fizzle implementation (CR 608.2b).
2	//!
3	//! A spell whose targets are all illegal when it tries to resolve should
4	//! be countered by game rules BEFORE on_resolve is called. This is different
5	//! from on_resolve checking targets and doing nothing — the spell should
6	//! never resolve at all.
7	//!
8	//! These tests verify the mechanism, not just the outcome.
9	
10	mod common;
11	
12	use common::*;
13	use mtg_engine::actions::{Action, Target};
14	use mtg_engine::cards::CardRegistry;
15	use mtg_engine::engine;
16	use mtg_engine::events::GameEvent;
17	use mtg_engine::types::*;
18	
19	fn registry() -> CardRegistry {
20	    CardRegistry::with_all_cards()
21	}
22	
23	// ════════════════════════════════════════════════════════════════════
24	// Mechanism test: SpellResolved event should NOT be emitted for fizzle
25	// ════════════════════════════════════════════════════════════════════
26	
27	/// When a spell fizzles, the engine should NOT emit SpellResolved.
28	/// A fizzled spell was countered by game rules — it did not resolve.
29	#[test]
30	fn fizzled_spell_does_not_emit_resolved_event() {
31	    let reg = registry();
32	    let mut state = game_at_step(Step::PrecombatMain, P0);
33	
34	    let creature = ready_creature(&mut state, P1, 3, 3);
35	    let bolt = castable_spell(&mut state, &reg, "Lightning Bolt", P0);
36	
37	    state = engine::submit_action(
38	        &state,
39	        &Action::CastSpell { object_id: bolt, targets: vec![Target::Object(creature)], sacrifice: None, exile_count: None, alternative_cost: None },
40	        &reg,
41	    );
42	
43	    // Target dies before resolution.
44	    state.move_object(creature, Zone::Graveyard);
45	    state.events.clear();
46	
47	    mtg_engine::stack::resolve_top_of_stack(&mut state, &reg);
48	
49	    // Should NOT have a SpellResolved event — the spell fizzled.
50	    let has_resolved = state.events.iter().any(|e| {
51	        matches!(e, GameEvent::SpellResolved { object } if *object == bolt)
52	    });
53	    assert!(!has_resolved,
54	        "Fizzled spell should NOT emit SpellResolved — it was countered by game rules, not resolved (CR 608.2b)");
55	}
56	
57	/// A spell that resolves normally SHOULD emit SpellResolved.
58	#[test]
59	fn resolved_spell_emits_resolved_event() {
60	    let reg = registry();
61	    let mut state = game_at_step(Step::PrecombatMain, P0);
62	
63	    let creature = ready_creature(&mut state, P1, 3, 3);
64	    let bolt = castable_spell(&mut state, &reg, "Lightning Bolt", P0);
65	
66	    state = engine::submit_action(
67	        &state,
68	        &Action::CastSpell { object_id: bolt, targets: vec![Target::Object(creature)], sacrifice: None, exile_count: None, alternative_cost: None },
69	        &reg,
70	    );
71	    state.events.clear();
72	
73	    // Target is still on the battlefield — spell resolves normally.
74	    mtg_engine::stack::resolve_top_of_stack(&mut state, &reg);
75	
76	    let has_resolved = state.events.iter().any(|e| {
77	        matches!(e, GameEvent::SpellResolved { object } if *object == bolt)
78	    });
79	    assert!(has_resolved,
80	        "Spell with legal target should emit SpellResolved");
81	}
82	
83	// ════════════════════════════════════════════════════════════════════
84	// Mechanism test: on_resolve should NOT be called for fizzle
85	//
86	// We test this using Swords to Plowshares, which exiles a creature
87	// AND causes its controller to gain life. If on_resolve runs but the
88	// zone check saves us, the life gain won't happen — but that's the
89	// wrong reason. We verify via the SpellResolved event instead.
90	//
91	// More importantly: if someone later writes a card that does
92	// "deal damage to target creature; draw a card", the fizzle must
93	// prevent BOTH effects. We simulate this with a two-part test.
94	// ════════════════════════════════════════════════════════════════════
95	
96	/// Swords to Plowshares fizzle: no exile, no life gain, no SpellResolved.
97	#[test]
98	fn swords_fizzle_no_side_effects() {
99	    let reg = registry();
100	    let mut state = game_at_step(Step::PrecombatMain, P0);
101	
102	    let creature = ready_creature(&mut state, P1, 5, 5);
103	    let swords = castable_spell(&mut state, &reg, "Swords to Plowshares", P0);
104	
105	    state = engine::submit_action(
106	        &state,
107	        &Action::CastSpell { object_id: swords, targets: vec![Target::Object(creature)], sacrifice: None, exile_count: None, alternative_cost: None },
108	        &reg,
109	    );
110	
111	    // Target leaves battlefield before resolution.
112	    state.move_object(creature, Zone::Exile);
113	    state.events.clear();
114	
115	    mtg_engine::stack::resolve_top_of_stack(&mut state, &reg);
116	
117	    // No SpellResolved — fizzled.
118	    let has_resolved = state.events.iter().any(|e| {
119	        matches!(e, GameEvent::SpellResolved { .. })
120	    });
121	    assert!(!has_resolved,
122	        "Swords to Plowshares should fizzle (not resolve) when target is gone");
123	
124	    // P1 should NOT have gained life (the creature was 5/5).
125	    assert_eq!(state.get_player(P1).life, 20,
126	        "No life gain from fizzled Swords to Plowshares");
127	}
128	
129	// ════════════════════════════════════════════════════════════════════
130	// Flashback fizzle: should go to exile, not graveyard
131	// ════════════════════════════════════════════════════════════════════
132	
133	/// A flashback spell that fizzles should still be exiled (not go to graveyard).
134	/// The "exile instead of graveyard" replacement applies regardless of whether
135	/// the spell resolved or fizzled.
136	#[test]
137	fn flashback_spell_fizzle_goes_to_exile() {
138	    let reg = registry();
139	    let mut state = game_at_step(Step::PrecombatMain, P0);
140	
141	    // Put Geistflame in graveyard (for flashback).
142	    let gf_id = reg.get_id_by_name("Geistflame").unwrap();
143	    let geistflame = state.create_object(gf_id, P0, Zone::Graveyard, None, None);
144	    state.get_object_mut(geistflame).unwrap().name = "Geistflame".into();
145	
146	    // Add flashback mana ({3}{R}).
147	    state.get_player_mut(P0).mana_pool.add(ManaType::Red, 1);
148	    state.get_player_mut(P0).mana_pool.add(ManaType::Colorless, 3);
149	
150	    let creature = ready_creature(&mut state, P1, 2, 2);
151	
152	    // Cast with flashback.
153	    state = engine::submit_action(
154	        &state,
155	        &Action::CastSpell { object_id: geistflame, targets: vec![Target::Object(creature)], sacrifice: None, exile_count: None, alternative_cost: None },
156	        &reg,
157	    );
158	    assert!(state.get_object(geistflame).unwrap().cast_with_flashback);
159	
160	    // Target dies before resolution.
161	    state.move_object(creature, Zone::Graveyard);
162	
163	    mtg_engine::stack::resolve_top_of_stack(&mut state, &reg);
164	
165	    // Flashback spell should be in exile (not graveyard), even though it fizzled.
166	    assert_eq!(state.get_object(geistflame).unwrap().zone, Zone::Exile,
167	        "Flashback spell that fizzles should still go to exile, not graveyard");
168	}
169	
170	/// A flashback spell that fizzles should NOT emit SpellResolved.
171	/// Before the fizzle fix, this would have emitted SpellResolved because
172	/// on_resolve was always called — it just happened to not deal damage
173	/// because the target was gone. The spell was treated as "resolved" when
174	/// it should have been "countered by game rules."
175	#[test]
176	fn flashback_spell_fizzle_no_resolved_event() {
177	    let reg = registry();
178	    let mut state = game_at_step(Step::PrecombatMain, P0);
179	
180	    let gf_id = reg.get_id_by_name("Geistflame").unwrap();
181	    let geistflame = state.create_object(gf_id, P0, Zone::Graveyard, None, None);
182	    state.get_object_mut(geistflame).unwrap().name = "Geistflame".into();
183	
184	    state.get_player_mut(P0).mana_pool.add(ManaType::Red, 1);
185	    state.get_player_mut(P0).mana_pool.add(ManaType::Colorless, 3);
186	
187	    let creature = ready_creature(&mut state, P1, 2, 2);
188	
189	    state = engine::submit_action(
190	        &state,
191	        &Action::CastSpell { object_id: geistflame, targets: vec![Target::Object(creature)], sacrifice: None, exile_count: None, alternative_cost: None },
192	        &reg,
193	    );
194	
195	    // Target dies before resolution.
196	    state.move_object(creature, Zone::Graveyard);
197	    state.events.clear();
198	
199	    mtg_engine::stack::resolve_top_of_stack(&mut state, &reg);
200	
201	    // Should NOT emit SpellResolved — the spell fizzled.
202	    let has_resolved = state.events.iter().any(|e| {
203	        matches!(e, GameEvent::SpellResolved { object } if *object == geistflame)
204	    });
205	    assert!(!has_resolved,
206	        "Flashback spell that fizzles should NOT emit SpellResolved — \
207	         it was countered by game rules, not resolved");
208	
209	    // Should still be in exile (flashback replacement applies to fizzled spells too).
210	    assert_eq!(state.get_object(geistflame).unwrap().zone, Zone::Exile);
211	
212	    // P1 should not have taken damage.
213	    assert_eq!(state.get_player(P1).life, 20);
214	}
215	
216	// ════════════════════════════════════════════════════════════════════
217	// Counterspell fizzle: target spell already left the stack
218	// ════════════════════════════════════════════════════════════════════
